// Exact diameters for sorting by restricted reversals (conjecture 007, Claude).
//
//	go run bfs.go -max 11 -lengths prime -output experiment.json
//
// The Cayley graph of S_n generated by reversing a contiguous block of length L
// (L in the allowed set, at any position) is vertex-transitive, so the diameter
// equals the largest distance from the identity. We BFS over all n! permutations,
// indexed by their Lehmer-code rank, storing one distance byte per permutation.
package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"os"
	"time"
)

func isPrime(k int) bool {
	if k < 2 {
		return false
	}
	for d := 2; d*d <= k; d++ {
		if k%d == 0 {
			return false
		}
	}
	return true
}

func factorial(n int) int {
	f := 1
	for i := 2; i <= n; i++ {
		f *= i
	}
	return f
}

// rank and unrank via Lehmer code (n <= 12)
func rank(p []int8) int {
	n := len(p)
	r := 0
	for i := 0; i < n; i++ {
		c := 0
		for j := i + 1; j < n; j++ {
			if p[j] < p[i] {
				c++
			}
		}
		r = r*(n-i) + c
	}
	return r
}

func unrank(r, n int, p []int8, fact []int) {
	avail := make([]int8, n)
	for i := range avail {
		avail[i] = int8(i)
	}
	for i := 0; i < n; i++ {
		f := fact[n-1-i]
		c := r / f
		r %= f
		p[i] = avail[c]
		avail = append(avail[:c], avail[c+1:]...)
	}
}

type result struct {
	N          int     `json:"n"`
	Lengths    []int   `json:"lengths"`
	Diameter   int     `json:"diameter"`
	Farthest   int     `json:"farthest_count"`
	Examples   [][]int `json:"farthest_examples"`
	Levels     []int   `json:"level_sizes"`
	Seconds    float64 `json:"seconds"`
}

func run(n int, lengths []int) result {
	start := time.Now()
	N := factorial(n)
	fact := make([]int, n+1)
	fact[0] = 1
	for i := 1; i <= n; i++ {
		fact[i] = fact[i-1] * i
	}
	dist := make([]uint8, N)
	for i := range dist {
		dist[i] = 255
	}
	id := make([]int8, n)
	for i := range id {
		id[i] = int8(i)
	}
	frontier := []int32{int32(rank(id))}
	dist[frontier[0]] = 0
	levels := []int{1}
	p := make([]int8, n)
	d := 0
	for len(frontier) > 0 {
		var next []int32
		for _, r := range frontier {
			unrank(int(r), n, p, fact)
			for _, L := range lengths {
				for i := 0; i+L <= n; i++ {
					for a, b := i, i+L-1; a < b; a, b = a+1, b-1 {
						p[a], p[b] = p[b], p[a]
					}
					q := rank(p)
					if dist[q] == 255 {
						dist[q] = uint8(d + 1)
						next = append(next, int32(q))
					}
					for a, b := i, i+L-1; a < b; a, b = a+1, b-1 {
						p[a], p[b] = p[b], p[a]
					}
				}
			}
		}
		if len(next) == 0 {
			break
		}
		d++
		levels = append(levels, len(next))
		frontier = next
	}
	res := result{N: n, Lengths: lengths, Diameter: d, Farthest: len(frontier), Levels: levels}
	for k, r := range frontier {
		if k >= 8 {
			break
		}
		unrank(int(r), n, p, fact)
		ex := make([]int, n)
		for i, v := range p {
			ex[i] = int(v) + 1
		}
		res.Examples = append(res.Examples, ex)
	}
	reached := 0
	for _, v := range dist {
		if v != 255 {
			reached++
		}
	}
	if reached != N {
		panic(fmt.Sprintf("n=%d: only %d of %d permutations reached", n, reached, N))
	}
	res.Seconds = time.Since(start).Seconds()
	return res
}

func main() {
	maxN := flag.Int("max", 11, "largest n")
	minN := flag.Int("min", 2, "smallest n")
	which := flag.String("lengths", "prime", "allowed lengths: prime | all | odd | twothree")
	output := flag.String("output", "experiment.json", "output JSON")
	flag.Parse()
	var results []result
	for n := *minN; n <= *maxN; n++ {
		var lengths []int
		for L := 2; L <= n; L++ {
			ok := false
			switch *which {
			case "prime":
				ok = isPrime(L)
			case "all":
				ok = true
			case "odd":
				ok = L%2 == 1 || L == 2
			case "twothree":
				ok = L == 2 || L == 3
			}
			if ok {
				lengths = append(lengths, L)
			}
		}
		r := run(n, lengths)
		fmt.Fprintf(os.Stderr, "n=%2d lengths=%v diameter=%d farthest=%d (%.1fs)\n", n, lengths, r.Diameter, r.Farthest, r.Seconds)
		results = append(results, r)
		out, _ := json.MarshalIndent(map[string]any{
			"implementation": "bfs.go (Claude)",
			"lengths_rule":   *which,
			"results":        results,
			"scope":          "Exact BFS over all of S_n for each listed n.",
		}, "", "  ")
		if err := os.WriteFile(*output, append(out, '\n'), 0o644); err != nil {
			panic(err)
		}
	}
}
